// Auto-composed skeleton for PipelineContracts
// Pattern: pipeline
// Stubs: stream-io

include "result.dfy"

// Pattern: Pipeline (Approach 3 — pre-written body with parameters)
// responsibility: Universal request handler — parse → validate → transform → store → respond
// test: HandleRequest("task|create|Buy groceries") returns Success(1)
// test: HandleRequest("task|create|") returns Failure("validation failed: empty title")
// test: HandleRequest("") returns Failure("parse failed: empty input")
// test: HandleRequest("task|create|Buy groceries|extra") returns Failure("parse failed: too many fields")
//
// This is the UNIVERSAL panel. Every project uses this as the foundation.
// The architect names it for the system's role (WorkflowPipeline, TaskSchedulerPipeline, etc.)
// and customizes the entity type, validation rules, and transformation.
// Specialist patterns (state-machine, graph, cache, scheduler) bolt on when needed.
//
// Parameters (architect customizes these):
//   inputDelimiter: string — field separator in input (default "|")
//   minFields: int — minimum required fields (default 2: command + action)
//   maxFields: int — maximum allowed fields (default 3: command + action + payload)
//   entityType: datatype — the domain entity (default: Record)
//
// Pre-cut planks: the parse step, validate step, transform step, store step,
// and result building are all pre-written and Z3-proven. The architect sets
// the parameters and entity type. Imp's job is empty or near-empty.

include "result.dfy"

// === Domain Entity (architect customizes) ===
datatype Entity =
  | Record(id: int, command: string, action: string, payload: string)

// === Stage 1: PARSE — split delimited input into fields ===

function GetDelimiter(delimiter: string): char
  requires |delimiter| == 1
{
  delimiter[0]
}

method ParseInput(input: string, delimiter: string) returns (fields: seq<string>)
  requires |input| > 0
  requires |delimiter| == 1
  ensures |fields| >= 1
  decreases |input|
{
  var delim := GetDelimiter(delimiter);
  fields := [];
  var currentField := "";
  var i := 0;
  while i < |input|
    invariant 0 <= i <= |input|
    invariant |fields| >= 0
    decreases |input| - i
  {
    if input[i] == delim {
      fields := fields + [currentField];
      currentField := "";
    } else {
      currentField := currentField + [input[i]];
    }
    i := i + 1;
  }
  fields := fields + [currentField];
}

// === Stage 2: VALIDATE — check parsed fields against rules ===

datatype ValidationResult =
  | Valid
  | Invalid(errors: seq<string>)

method ValidateFields(fields: seq<string>, minFields: int, maxFields: int) returns (result: ValidationResult)
  requires minFields >= 0
  requires maxFields >= minFields
  ensures result.Valid? ==> |fields| >= minFields && |fields| <= maxFields
  ensures result.Invalid? ==> |result.errors| >= 1
  decreases |fields|
{
  var errors := [];
  if |fields| < minFields {
    errors := errors + ["validation failed: too few fields"];
  }
  if |fields| > maxFields {
    errors := errors + ["validation failed: too many fields"];
  }
  if |fields| > 0 && |fields[0]| == 0 {
    errors := errors + ["validation failed: empty command"];
  }
  if |fields| > 1 && |fields[1]| == 0 {
    errors := errors + ["validation failed: empty action"];
  }
  if |errors| == 0 {
    result := Valid;
  } else {
    result := Invalid(errors);
  }
}

// === Stage 3: TRANSFORM — convert validated fields into domain entity ===

method TransformToEntity(fields: seq<string>, nextId: int) returns (entity: Entity)
  requires |fields| >= 2
  ensures entity.id == nextId
  decreases |fields|
{
  var payload := if |fields| >= 3 then fields[2] else "";
  entity := Record(nextId, fields[0], fields[1], payload);
}

// === Stage 4: STORE — add entity to in-memory store with ID uniqueness ===

predicate NoDuplicateIds(entities: seq<Entity>)
{
  forall i, j :: 0 <= i < j < |entities| ==> entities[i].id != entities[j].id
}

method StoreEntity(entities: seq<Entity>, entity: Entity) returns (result: Result<seq<Entity>>)
  requires NoDuplicateIds(entities)
  ensures result.Success? ==> NoDuplicateIds(result.value)
  ensures result.Success? ==> |result.value| == |entities| + 1
  ensures result.Failure? ==> result.error == "duplicate id"
  decreases |entities|
{
  var i := 0;
  var found := false;
  while i < |entities|
    invariant 0 <= i <= |entities|
    invariant NoDuplicateIds(entities)
    invariant found ==> exists j :: 0 <= j < |entities| && entities[j].id == entity.id
    invariant !found ==> forall j :: 0 <= j < i ==> entities[j].id != entity.id
    decreases |entities| - i
  {
    if entities[i].id == entity.id {
      found := true;
    }
    i := i + 1;
  }
  if found {
    result := Failure("duplicate id");
  } else {
    result := Success(entities + [entity]);
  }
}
// === Stage 5: PIPELINE ORCHESTRATION — run all stages in sequence ===

method HandleRequest(
    input: string,
    delimiter: string,
    minFields: int,
    maxFields: int,
    entities: seq<Entity>,
    nextId: int
) returns (result: Result<seq<Entity>>)
  requires |input| > 0
  requires |delimiter| == 1
  requires minFields >= 2
  requires maxFields >= minFields
  requires NoDuplicateIds(entities)
  ensures result.Success? ==> NoDuplicateIds(result.value)
  ensures result.Failure? ==> true
  decreases |entities|
{
  // Stage 1: Parse
  var fields := ParseInput(input, delimiter);

  // Stage 2: Validate
  var validation := ValidateFields(fields, minFields, maxFields);
  if validation.Invalid? {
    result := Failure(validation.errors[0]);
    return;
  }

  // After validation, fields count is within [minFields, maxFields]
  // The architect sets minFields=2, maxFields=3 for standard commands
  assert |fields| >= minFields;
  assert |fields| <= maxFields;

  // Stage 3: Transform
  assert |fields| >= 2;
  var entity := TransformToEntity(fields, nextId);

  // Stage 4: Store
  assert NoDuplicateIds(entities);
  result := StoreEntity(entities, entity);
}

// === Utility: Query stored entities by command ===

method QueryByCommand(entities: seq<Entity>, command: string) returns (matches: seq<Entity>)
  ensures |matches| <= |entities|
  decreases |entities|
{
  matches := [];
  var i := 0;
  while i < |entities|
    invariant 0 <= i <= |entities|
    invariant |matches| <= i
    decreases |entities| - i
  {
    if entities[i].command == command {
      matches := matches + [entities[i]];
    }
    i := i + 1;
  }
}

// === Utility: Count entities ===

method CountEntities(entities: seq<Entity>) returns (count: int)
  ensures count == |entities|
  ensures count >= 0
  decreases |entities|
{
  count := |entities|;
}

// === Utility: Get next available ID ===

method GetNextId(entities: seq<Entity>) returns (nextId: int)
  requires NoDuplicateIds(entities)
  ensures nextId >= 0
  ensures forall i :: 0 <= i < |entities| ==> entities[i].id != nextId
  decreases |entities|
{
  nextId := 0;
  var i := 0;
  while i < |entities|
    invariant 0 <= i <= |entities|
    invariant nextId >= 0
    invariant forall j :: 0 <= j < i ==> entities[j].id < nextId
    decreases |entities| - i
  {
    if entities[i].id >= nextId {
      nextId := entities[i].id + 1;
    }
    i := i + 1;
  }
}

// ---- stream-io portals ----
// Stubs: Stream I/O portals
// Pre-cut {:extern} declarations for stream operations.
// Attach to patterns that process data incrementally.

// Open a stream for reading
method {:extern} OpenStream(path: string) returns (streamId: int)
  requires |path| > 0
  ensures streamId >= 0

// Read next chunk from stream
method {:extern} ReadChunk(streamId: int, maxBytes: int) returns (chunk: string)
  requires streamId >= 0
  requires maxBytes > 0
  ensures |chunk| >= 0

// Close a stream
method {:extern} CloseStream(streamId: int)
  requires streamId >= 0

// Check if stream has more data
method {:extern} HasMore(streamId: int) returns (hasMore: bool)
  requires streamId >= 0

// Auto-composed skeleton for DagResolver
// Pattern: graph
// Stubs: console-io, stream-io

include "result.dfy"

// Pattern: Graph (Approach 3 — pre-written body with parameters)
// responsibility: Nodes, edges, traversal, and search
// test: HasEdge([[], [2], [3], []], 1, 2) returns true
// test: HasEdge([[], [2], [3], []], 2, 3) returns true
// test: HasEdge([[], [2], [3], []], 1, 3) returns false
// test: Reachable([[], [2], [3], []], 1, 3) returns true
// test: Reachable([[], [2], [3], []], 3, 1) returns false
//
// Parameters:
//   directed: bool — whether edges are directed (default true)
//   maxNodes: int — capacity hint for node allocation

include "result.dfy"

// Adjacency list: adj[node] = sequence of neighbor node IDs.
// Node IDs are integers in [0, |adj|).

// Add a new node (appends an empty neighbor list)
method AddNode(adj: seq<seq<int>>) returns (newAdj: seq<seq<int>>)
  ensures |newAdj| == |adj| + 1
  ensures newAdj[|adj|] == []
  ensures forall i :: 0 <= i < |adj| ==> newAdj[i] == adj[i]
{
  newAdj := adj + [[]];
}

// Add a directed edge from -> to
method AddEdge(adj: seq<seq<int>>, from: int, to: int) returns (newAdj: seq<seq<int>>)
  requires 0 <= from < |adj|
  requires 0 <= to < |adj|
  ensures |newAdj| == |adj|
  ensures forall i :: 0 <= i < |adj| && i != from ==> newAdj[i] == adj[i]
  ensures to in newAdj[from]
{
  newAdj := adj[..from] + [adj[from] + [to]] + adj[from + 1..];
}

// Check if an edge from -> to exists
method HasEdge(adj: seq<seq<int>>, from: int, to: int) returns (found: bool)
  requires 0 <= from < |adj|
  ensures found ==> exists k :: 0 <= k < |adj[from]| && adj[from][k] == to
{
  found := false;
  ghost var foundIdx := -1;
  var i := 0;
  while i < |adj[from]|
    invariant 0 <= i <= |adj[from]|
    invariant -1 <= foundIdx < i
    invariant found == (foundIdx >= 0)
    invariant foundIdx >= 0 ==> adj[from][foundIdx] == to
    decreases |adj[from]| - i
  {
    if !found && adj[from][i] == to {
      found := true;
      foundIdx := i;
    }
    i := i + 1;
  }
}

// Helper: prove that to is in the sequence (used to establish membership)
function InSeq(s: seq<int>, to: int): bool
  decreases |s|
{
  if |s| == 0 then false
  else if s[0] == to then true
  else InSeq(s[1..], to)
}

// Get the neighbor list for a node
function GetNeighbors(adj: seq<seq<int>>, node: int): seq<int>
  requires 0 <= node < |adj|
{
  adj[node]
}

// Check if target is reachable from start (recursive DFS)
function Reachable(adj: seq<seq<int>>, start: int, target: int): bool
  requires 0 <= start < |adj|
  requires 0 <= target < |adj|
{
  ReachableDFS(adj, start, target, set i | 0 <= i < |adj|)
}

// Recursive DFS helper: explores unvisited nodes
function ReachableDFS(adj: seq<seq<int>>, start: int, target: int, unvisited: set<int>): bool
  requires 0 <= start < |adj|
  requires 0 <= target < |adj|
  requires start in unvisited
  requires forall n :: n in unvisited ==> 0 <= n < |adj|
  decreases |unvisited|, 0
{
  if start == target then true
  else ReachableViaNeighbors(adj, target, unvisited - {start}, adj[start])
}

// Iterate over neighbors, recursing into unvisited ones
function ReachableViaNeighbors(adj: seq<seq<int>>, target: int, unvisited: set<int>, neighbors: seq<int>): bool
  requires 0 <= target < |adj|
  requires forall n :: n in unvisited ==> 0 <= n < |adj|
  decreases |unvisited|, |neighbors|
{
  if |neighbors| == 0 then false
  else if 0 <= neighbors[0] < |adj| && neighbors[0] in unvisited then
    ReachableDFS(adj, neighbors[0], target, unvisited) || ReachableViaNeighbors(adj, target, unvisited, neighbors[1..])
  else
    ReachableViaNeighbors(adj, target, unvisited, neighbors[1..])
}

// Search: check reachability, returning a Result
method Search(adj: seq<seq<int>>, start: int, target: int) returns (result: Result<bool>)
  requires 0 <= start < |adj|
  requires 0 <= target < |adj|
  ensures result.Success?
  ensures result.value == Reachable(adj, start, target)
{
  result := Success(Reachable(adj, start, target));
}

// ---- console-io portals ----
// Stubs: Console I/O portals
// Pre-cut {:extern} declarations for console operations.
// Attach to patterns that interact with the user.

// Print a line to console
method {:extern} PrintLine(text: string)
  ensures true

// Print without newline
method {:extern} Print(text: string)
  ensures true

// Read a line from console
method {:extern} ReadLine() returns (line: string)
  ensures |line| >= 0

// Read a character from console
method {:extern} ReadChar() returns (ch: string)
  ensures |ch| <= 1

// Clear the console
method {:extern} ClearScreen()
  ensures true

// ---- stream-io portals ----
// Stubs: Stream I/O portals
// Pre-cut {:extern} declarations for stream operations.
// Attach to patterns that process data incrementally.

// Open a stream for reading
method {:extern} OpenStream(path: string) returns (streamId: int)
  requires |path| > 0
  ensures streamId >= 0

// Read next chunk from stream
method {:extern} ReadChunk(streamId: int, maxBytes: int) returns (chunk: string)
  requires streamId >= 0
  requires maxBytes > 0
  ensures |chunk| >= 0

// Close a stream
method {:extern} CloseStream(streamId: int)
  requires streamId >= 0

// Check if stream has more data
method {:extern} HasMore(streamId: int) returns (hasMore: bool)
  requires streamId >= 0

// Auto-composed skeleton for JobScheduler
// Pattern: scheduler
// Stubs: none

include "result.dfy"

// Pattern: Scheduler (Approach 3 — pre-written body with parameters)
// responsibility: Enqueue, dequeue, and prioritize tasks
// test: Dequeue([Entry(Task(1, "a"), 5), Entry(Task(2, "b"), 10)]) returns Success(Entry(Task(2, "b"), 10))
// test: Dequeue([Entry(Task(1, "a"), 5)]) returns Success(Entry(Task(1, "a"), 5))
// test: Peek([Entry(Task(1, "a"), 5), Entry(Task(2, "b"), 10)]) returns Success(Entry(Task(2, "b"), 10))
// test: Prioritize([Entry(Task(1, "a"), 5), Entry(Task(2, "b"), 10)]) returns [Entry(Task(2, "b"), 10), Entry(Task(1, "a"), 5)]
//
// Parameters:
//   policy: string — "priority" (highest first) or "fifo" (first in first out)
//   maxQueueSize: int — maximum queue depth (0 = unlimited)

include "result.dfy"

datatype Task = Task(id: int, name: string)
datatype Entry = Entry(task: Task, priority: int)

// Predicate: sequence is sorted in descending priority order
predicate IsSortedDesc(s: seq<Entry>)
{
  forall i :: 0 <= i < |s| - 1 ==> s[i].priority >= s[i + 1].priority
}

// Enqueue: add an entry to the end of the queue
method Enqueue(queue: seq<Entry>, entry: Entry) returns (newQueue: seq<Entry>)
  ensures |newQueue| == |queue| + 1
  ensures newQueue[|queue|] == entry
  ensures forall i :: 0 <= i < |queue| ==> newQueue[i] == queue[i]
{
  newQueue := queue + [entry];
}

// Dequeue: remove and return the highest-priority entry
method Dequeue(queue: seq<Entry>) returns (result: Result<Entry>, newQueue: seq<Entry>)
  requires |queue| > 0
  ensures result.Success?
  ensures |newQueue| == |queue| - 1
  ensures forall j :: 0 <= j < |queue| ==> result.value.priority >= queue[j].priority
  ensures result.value in queue
  decreases |queue|
{
  var maxIdx := 0;
  var i := 1;
  while i < |queue|
    invariant 0 <= maxIdx < i <= |queue|
    invariant forall j :: 0 <= j < i ==> queue[j].priority <= queue[maxIdx].priority
    decreases |queue| - i
  {
    if queue[i].priority > queue[maxIdx].priority {
      maxIdx := i;
    }
    i := i + 1;
  }
  result := Success(queue[maxIdx]);
  newQueue := queue[..maxIdx] + queue[maxIdx + 1..];
}

// Peek: return the highest-priority entry without removing it
method Peek(queue: seq<Entry>) returns (result: Result<Entry>)
  requires |queue| > 0
  ensures result.Success?
  ensures forall j :: 0 <= j < |queue| ==> result.value.priority >= queue[j].priority
  ensures result.value in queue
  decreases |queue|
{
  var maxIdx := 0;
  var i := 1;
  while i < |queue|
    invariant 0 <= maxIdx < i <= |queue|
    invariant forall j :: 0 <= j < i ==> queue[j].priority <= queue[maxIdx].priority
    decreases |queue| - i
  {
    if queue[i].priority > queue[maxIdx].priority {
      maxIdx := i;
    }
    i := i + 1;
  }
  result := Success(queue[maxIdx]);
}

// Insert an entry into a sorted queue, maintaining descending priority order
function InsertSorted(sorted: seq<Entry>, e: Entry): seq<Entry>
  requires IsSortedDesc(sorted)
  ensures |InsertSorted(sorted, e)| == |sorted| + 1
  ensures IsSortedDesc(InsertSorted(sorted, e))
  decreases |sorted|
{
  if |sorted| == 0 then [e]
  else if e.priority >= sorted[0].priority then [e] + sorted
  else [sorted[0]] + InsertSorted(sorted[1..], e)
}

// Prioritize: sort the queue by priority (highest first) using insertion sort
method Prioritize(queue: seq<Entry>) returns (sorted: seq<Entry>)
  ensures |sorted| == |queue|
  ensures IsSortedDesc(sorted)
  decreases |queue|
{
  sorted := [];
  var i := 0;
  while i < |queue|
    invariant 0 <= i <= |queue|
    invariant |sorted| == i
    invariant IsSortedDesc(sorted)
    decreases |queue| - i
  {
    sorted := InsertSorted(sorted, queue[i]);
    i := i + 1;
  }
}

// Auto-composed skeleton for StepExecutor
// Pattern: state-machine
// Stubs: none

// Pattern: State Machine (Approach 3 — pre-written body with parameters)
// responsibility: Finite states with guarded transitions
// test: Transition(Idle, "start") returns Active
// test: Transition(Active, "complete") returns Completed
// test: Transition(Idle, "complete") returns Idle (invalid transition)
//
// Parameters:
//   states: the datatype variants (customized per domain)
//   events: the event strings (customized per domain)
//   guards: which transitions are valid (the match body)

datatype State =
  | Idle
  | Active
  | Completed
  | Failed

// Transition: state x event -> state
// Invalid transitions stay in current state
method Transition(current: State, event: string) returns (next: State)
  ensures next == Idle || next == Active || next == Completed || next == Failed
{
  match current
  case Idle =>
    if event == "start" {
      next := Active;
    } else {
      next := Idle;
    }
  case Active =>
    if event == "complete" {
      next := Completed;
    } else if event == "fail" {
      next := Failed;
    } else {
      next := Active;
    }
  case Completed =>
    if event == "reset" {
      next := Idle;
    } else {
      next := Completed;
    }
  case Failed =>
    if event == "reset" {
      next := Idle;
    } else {
      next := Failed;
    }
}

// Check if a transition is valid without executing it
function IsValidTransition(current: State, event: string): bool
{
  match current
  case Idle => event == "start"
  case Active => event == "complete" || event == "fail"
  case Completed => event == "reset"
  case Failed => event == "reset"
}

// Get all valid events for a state
method GetValidEvents(current: State) returns (events: seq<string>)
  ensures |events| >= 0
{
  if current == Idle {
    events := ["start"];
  } else if current == Active {
    events := ["complete", "fail"];
  } else if current == Completed {
    events := ["reset"];
  } else {
    events := ["reset"];
  }
}

// Auto-composed skeleton for ExpressionEvaluator
// Pattern: parser
// Stubs: none

include "result.dfy"

// Pattern: Parser (Approach 3 — pre-written body with parameters)
// responsibility: Parse delimited input into typed fields
// test: ParseLine("a,b,c", ",") returns ["a","b","c"]
// test: ParseLine("hello", ",") returns ["hello"]
// test: ParseLine("", ",") returns []
//
// Parameters (architect customizes these):
//   delimiter: string — single-char field separator (default ",")
//   quoteChar: string — quote character for quoted fields (default "\"", "" = none)
//   hasHeader: bool — whether first line is a header (affects ParseLines only)
//
// Pre-cut planks: the iteration loop, field accumulation, delimiter matching,
// and result building are all pre-written and Z3-proven. The architect sets
// the parameters. Imp's job is empty or near-empty.

include "result.dfy"

// Get the delimiter character (precondition ensures it exists)
function GetDelimiter(delimiter: string): char
  requires |delimiter| == 1
{
  delimiter[0]
}

// Parse a single delimited line into fields.
// Iterates characters, splits on delimiter, accumulates fields.
method ParseLine(input: string, delimiter: string) returns (fields: seq<string>)
  requires |input| > 0
  requires |delimiter| == 1
  ensures |fields| >= 1
  decreases |input|
{
  var delim := GetDelimiter(delimiter);
  fields := [];
  var currentField := "";
  var i := 0;

  while i < |input|
    invariant 0 <= i <= |input|
    invariant |fields| >= 0
    decreases |input| - i
  {
    if input[i] == delim {
      fields := fields + [currentField];
      currentField := "";
    } else {
      currentField := currentField + [input[i]];
    }
    i := i + 1;
  }
  // Append the last field (there's always at least one because input is non-empty)
  fields := fields + [currentField];
}

// Parse multiple lines. If hasHeader is true, the first line is dropped.
method ParseLines(input: string, delimiter: string, hasHeader: bool) returns (rows: seq<seq<string>>)
  requires |input| > 0
  requires |delimiter| == 1
  ensures |rows| >= 0
  decreases |input|
{
  var delim := GetDelimiter(delimiter);
  rows := [];
  var currentLine := "";
  var i := 0;
  var firstLine := hasHeader;

  while i < |input|
    invariant 0 <= i <= |input|
    decreases |input| - i
  {
    if input[i] == '\n' {
      if |currentLine| > 0 {
        if !firstLine {
          var fields := ParseLine(currentLine, delimiter);
          rows := rows + [fields];
        }
        firstLine := false;
        currentLine := "";
      }
    } else if input[i] != '\r' {
      currentLine := currentLine + [input[i]];
    }
    i := i + 1;
  }

  // Handle last line (no trailing newline)
  if |currentLine| > 0 && !firstLine {
    var fields := ParseLine(currentLine, delimiter);
    rows := rows + [fields];
  }
}

// Count fields in a delimited string (without allocating the result)
function CountFields(input: string, delimiter: string): int
  requires |delimiter| == 1
  decreases |input|
{
  if |input| == 0 then 1
  else if |input| == 1 then 1
  else
    (if input[0] == GetDelimiter(delimiter) then 1 + CountFields(input[1..], delimiter)
     else CountFields(input[1..], delimiter))
}

// Auto-composed skeleton for ArtifactManager
// Pattern: repository
// Stubs: none

include "result.dfy"

// Pattern: Repository (Approach 3 — pre-written body with parameters)
// responsibility: Store items with ID uniqueness, lookup, and update
// test: Add([], Record(1, "test", "data")) returns Success([Record(1, "test", "data")])
// test: Add([Record(1, "a", "b")], Record(1, "c", "d")) returns Failure("duplicate id")
//
// Parameters:
//   idField: string — name of the ID field (for error messages)
//   allowUpdate: bool — whether Add replaces existing IDs (default false)

include "result.dfy"

datatype Entity =
  | Record(id: int, name: string, data: string)

// Invariant: no duplicate IDs
predicate NoDuplicates(items: seq<Entity>)
{
  forall i, j :: 0 <= i < j < |items| ==> items[i].id != items[j].id
}

// Add: insert if ID not present, fail if duplicate
method Add(items: seq<Entity>, entity: Entity) returns (result: Result<seq<Entity>>)
  requires NoDuplicates(items)
  ensures result.Success? ==> |result.value| == |items| + 1
  ensures result.Failure? ==> result.error == "duplicate id"
  decreases |items|
{
  var i := 0;
  var found := false;
  while i < |items| && !found
    invariant 0 <= i <= |items|
    invariant NoDuplicates(items)
    decreases |items| - i
  {
    if items[i].id == entity.id {
      found := true;
    }
