// Pattern: parser
// Stubs: none

include "result.dfy"

// Pattern: Parser (Approach 3 — pre-written body with parameters)
// responsibility: Parse delimited input into typed fields
// test: ParseLine("a,b,c", ",") returns ["a","b","c"]
// test: ParseLine("hello", ",") returns ["hello"]
// test: ParseLine("", ",") returns []
//
// Parameters (architect customizes these):
//   delimiter: string — single-char field separator (default ",")
//   quoteChar: string — quote character for quoted fields (default "\"", "" = none)
//   hasHeader: bool — whether first line is a header (affects ParseLines only)
//
// Pre-cut planks: the iteration loop, field accumulation, delimiter matching,
// and result building are all pre-written and Z3-proven. The architect sets
// the parameters. Imp's job is empty or near-empty.

include "result.dfy"

// Get the delimiter character (precondition ensures it exists)
function GetDelimiter(delimiter: string): char
  requires |delimiter| == 1
{
  delimiter[0]
}

// Parse a single delimited line into fields.
// Iterates characters, splits on delimiter, accumulates fields.
method ParseLine(input: string, delimiter: string) returns (fields: seq<string>)
  requires |input| > 0
  requires |delimiter| == 1
  ensures |fields| >= 1
  decreases |input|
{
  var delim := GetDelimiter(delimiter);
  fields := [];
  var currentField := "";
  var i := 0;

  while i < |input|
    invariant 0 <= i <= |input|
    invariant |fields| >= 0
    decreases |input| - i
  {
    if input[i] == delim {
      fields := fields + [currentField];
      currentField := "";
    } else {
      currentField := currentField + [input[i]];
    }
    i := i + 1;
  }
  // Append the last field (there's always at least one because input is non-empty)
  fields := fields + [currentField];
}

// Parse multiple lines. If hasHeader is true, the first line is dropped.
method ParseLines(input: string, delimiter: string, hasHeader: bool) returns (rows: seq<seq<string>>)
  requires |input| > 0
  requires |delimiter| == 1
  ensures |rows| >= 0
  decreases |input|
{
  var delim := GetDelimiter(delimiter);
  rows := [];
  var currentLine := "";
  var i := 0;
  var firstLine := hasHeader;

  while i < |input|
    invariant 0 <= i <= |input|
    decreases |input| - i
  {
    if input[i] == '\n' {
      if |currentLine| > 0 {
        if !firstLine {
          var fields := ParseLine(currentLine, delimiter);
          rows := rows + [fields];
        }
        firstLine := false;
        currentLine := "";
      }
    } else if input[i] != '\r' {
      currentLine := currentLine + [input[i]];
    }
    i := i + 1;
  }

  // Handle last line (no trailing newline)
  if |currentLine| > 0 && !firstLine {
    var fields := ParseLine(currentLine, delimiter);
    rows := rows + [fields];
  }
}

// Count fields in a delimited string (without allocating the result)
function CountFields(input: string, delimiter: string): int
  requires |delimiter| == 1
  decreases |input|
{
  if |input| == 0 then 1
  else if |input| == 1 then 1
  else
    (if input[0] == GetDelimiter(delimiter) then 1 + CountFields(input[1..], delimiter)
     else CountFields(input[1..], delimiter))
}

// Auto-composed skeleton for ArtifactManager
// Pattern: repository
// Stubs: none

include "result.dfy"

// Pattern: Repository (Approach 3 — pre-written body with parameters)
// responsibility: Store items with ID uniqueness, lookup, and update
// test: Add([], Record(1, "test", "data")) returns Success([Record(1, "test", "data")])
// test: Add([Record(1, "a", "b")], Record(1, "c", "d")) returns Failure("duplicate id")
//
// Parameters:
//   idField: string — name of the ID field (for error messages)
//   allowUpdate: bool — whether Add replaces existing IDs (default false)

include "result.dfy"

datatype Entity =
  | Record(id: int, name: string, data: string)

// Invariant: no duplicate IDs
predicate NoDuplicates(items: seq<Entity>)
{
  forall i, j :: 0 <= i < j < |items| ==> items[i].id != items[j].id
}

// Add: insert if ID not present, fail if duplicate
method Add(items: seq<Entity>, entity: Entity) returns (result: Result<seq<Entity>>)
  requires NoDuplicates(items)
  ensures result.Success? ==> |result.value| == |items| + 1
  ensures result.Failure? ==> result.error == "duplicate id"
  decreases |items|
{
  var i := 0;
  var found := false;
  while i < |items| && !found
    invariant 0 <= i <= |items|
    invariant NoDuplicates(items)
    decreases |items| - i
  {
    if items[i].id == entity.id {
      found := true;
    }
    i := i + 1;
  }

  if found {
    result := Failure("duplicate id");
  } else {
    result := Success(items + [entity]);
  }
}

// Find: lookup by ID
method Find(items: seq<Entity>, id: int) returns (result: Result<Entity>)
  ensures result.Success? ==> result.value.id == id
  decreases |items|
{
  var i := 0;
  while i < |items|
    invariant 0 <= i <= |items|
    decreases |items| - i
  {
    if items[i].id == id {
      result := Success(items[i]);
      return;
    }
    i := i + 1;
  }
  result := Failure("not found");
}

// Remove: delete by ID
method Remove(items: seq<Entity>, id: int) returns (result: Result<seq<Entity>>)
  requires NoDuplicates(items)
  ensures result.Success? ==> |result.value| <= |items|
  decreases |items|
{
  var i := 0;
  var found := false;
  while i < |items| && !found
    invariant 0 <= i <= |items|
    decreases |items| - i
  {
    if items[i].id == id {
      found := true;
    }
    i := i + 1;
  }

  if found {
    var newItems := [];
    var j := 0;
    while j < |items|
      invariant 0 <= j <= |items|
      invariant |newItems| <= j
      decreases |items| - j
    {
      if items[j].id != id {
        newItems := newItems + [items[j]];
      }
      j := j + 1;
    }
    result := Success(newItems);
  } else {
    result := Failure("not found");
  }
}

// Auto-composed skeleton for NotificationSystem
// Pattern: observer
// Stubs: stream-io

include "result.dfy"

// Pattern: Observer (Approach 3 — pre-written body with parameters)
// responsibility: Publish/subscribe event bus
// test: Publish([], "click") returns 0
// test: Publish([Sub("a"), Sub("b")], "click") returns 2
// test: Subscribe([], "user1", "click") returns [Subscription("user1", "click")]
//
// Parameters:
//   eventFilter: string — if non-empty, only deliver events matching this name (default "")
//   maxSubscribers: int — cap on subscriber count (default 100)
//
// Pre-cut planks: the subscriber list, event matching, delivery counting,
// and subscribe/unsubscribe are all pre-written and Z3-proven. The architect
// sets the parameters. Imp's job is empty or near-empty.

include "result.dfy"

// A subscription pairs a subscriber ID with an event name it listens to.
datatype Subscription =
  | Sub(subscriberId: int, eventName: string)

// Invariant: no two subscriptions share the same subscriber+event pair.
predicate NoDupSubs(subs: seq<Subscription>)
{
  forall i, j :: 0 <= i < j < |subs| ==>
    !(subs[i].subscriberId == subs[j].subscriberId && subs[i].eventName == subs[j].eventName)
}

// Publish an event to all matching subscribers, returning the delivery count.
method Publish(subs: seq<Subscription>, eventName: string) returns (delivered: int)
  requires NoDupSubs(subs)
  ensures delivered >= 0
  ensures delivered <= |subs|
  decreases |subs|
{
  delivered := 0;
  var i := 0;
  while i < |subs|
    invariant 0 <= i <= |subs|
    invariant delivered <= i
    invariant NoDupSubs(subs)
    decreases |subs| - i
  {
    if subs[i].eventName == eventName {
      delivered := delivered + 1;
    }
    i := i + 1;
  }
}

// Subscribe: add a new subscription if not already present.
method Subscribe(subs: seq<Subscription>, subscriberId: int, eventName: string) returns (result: Result<seq<Subscription>>)
  requires NoDupSubs(subs)
  ensures result.Success? ==> |result.value| == |subs| + 1
  ensures result.Success? ==> NoDupSubs(result.value)
  ensures result.Failure? ==> result.error == "duplicate subscription"
  decreases |subs|
{
  var i := 0;
  var found := false;
  while i < |subs| && !found
    invariant 0 <= i <= |subs|
    invariant NoDupSubs(subs)
    invariant !found ==> (forall k :: 0 <= k < i ==>
      !(subs[k].subscriberId == subscriberId && subs[k].eventName == eventName))
    decreases |subs| - i
  {
    if subs[i].subscriberId == subscriberId && subs[i].eventName == eventName {
      found := true;
    }
    i := i + 1;
  }

  if found {
    result := Failure("duplicate subscription");
  } else {
    result := Success(subs + [Sub(subscriberId, eventName)]);
  }
}

// Unsubscribe: remove a subscriber-event pair.
method Unsubscribe(subs: seq<Subscription>, subscriberId: int, eventName: string) returns (result: Result<seq<Subscription>>)
  requires NoDupSubs(subs)
  ensures result.Success? ==> |result.value| == |subs| - 1
  ensures result.Success? ==> NoDupSubs(result.value)
  ensures result.Failure? ==> result.error == "subscription not found"
  decreases |subs|
{
  var i := 0;
  var found := false;
  var foundIdx := 0;
  while i < |subs| && !found
    invariant 0 <= i <= |subs|
    invariant NoDupSubs(subs)
    invariant !found ==> (forall k :: 0 <= k < i ==>
      !(subs[k].subscriberId == subscriberId && subs[k].eventName == eventName))
    invariant found ==> 0 <= foundIdx < |subs|
    invariant found ==> subs[foundIdx].subscriberId == subscriberId
    invariant found ==> subs[foundIdx].eventName == eventName
    decreases |subs| - i
  {
    if subs[i].subscriberId == subscriberId && subs[i].eventName == eventName {
      found := true;
      foundIdx := i;
    }
    i := i + 1;
  }

  if found {
    // Build result without the foundIdx element
    var newSubs := subs[..foundIdx] + subs[foundIdx + 1..];
    result := Success(newSubs);
  } else {
    result := Failure("subscription not found");
  }
}

// Count subscribers for a given event name.
method CountSubscribers(subs: seq<Subscription>, eventName: string) returns (count: int)
  ensures count >= 0
  ensures count <= |subs|
  decreases |subs|
{
  count := 0;
  var i := 0;
  while i < |subs|
    invariant 0 <= i <= |subs|
    invariant count <= i
    decreases |subs| - i
  {
    if subs[i].eventName == eventName {
      count := count + 1;
    }
    i := i + 1;
  }
}

